#!/usr/bin/env python3
"""Write firmware/src/update_keys.h from the release signing keys' public halves.

    python3 tools/release/make_update_keys.py main.pub.pem spare.pub.pem

The keys are ECDSA P-256 (openssl ecparam -name prime256v1 -genkey). The
private halves never come near this script or the repository.
"""
import subprocess
import sys

HEAD = '''/**
 * this file is part of ninepin-ux; released under the terms of the Eclipse
 * Public License 2.0 (EPL-2.0), https://spdx.org/licenses/EPL-2.0
 *
 * generated by tools/release/make_update_keys.py: the public halves of the
 * keys a release may be signed with (net_update.c), ecdsa p-256, as
 * uncompressed points. the first signs the releases; the second is a spare,
 * for a release that replaces the first.
 */

#ifndef _UPDATE_KEYS_H
#define _UPDATE_KEYS_H

#include <stdint.h>

#define UPDATE_KEY_BYTES 65
#define UPDATE_KEY_COUNT %d

static uint8_t const update_keys[UPDATE_KEY_COUNT][UPDATE_KEY_BYTES] = {
'''


def point(path):
    der = subprocess.run(["openssl", "ec", "-pubin", "-in", path, "-outform", "DER", "-conv_form", "uncompressed"],
                         check=True, capture_output=True).stdout
    raw = der[-65:]
    if len(der) != 91 or raw[0] != 4:
        sys.exit("%s: not a P-256 public key" % path)
    return raw


def main():
    paths = sys.argv[1:]
    if not paths:
        sys.exit(__doc__)
    out = HEAD % len(paths)
    for path in paths:
        raw = point(path)
        out += "    {\n"
        for i in range(0, 65, 13):
            out += "        " + " ".join("0x%02x," % b for b in raw[i:i + 13]) + "\n"
        out += "    },\n"
    out += "};\n\n#endif // _UPDATE_KEYS_H\n"
    open("firmware/src/update_keys.h", "w").write(out)
    print("firmware/src/update_keys.h: %d key(s)" % len(paths))


main()
